$excel = New-Object -ComObject Excel.Application; $excel.Visible = $false; $excel.DisplayAlerts = $false
$wb = $excel.Workbooks.Open("C:\Users\lutfi\OneDrive\Desktop\TTSH Intern\Coding projects\Attendance VBA\Attendance_Analyzer.xlsx", 0, $true)
$cfg = $wb.Worksheets.Item("Config")
Write-Output "=== Config rows 1-8, cols A-J ==="
for ($r=1; $r -le 8; $r++) { $vals = @(); for ($c=1; $c -le 10; $c++) { $vals += [string]$cfg.Cells.Item($r,$c).Text }; Write-Output ("R{0}: {1}" -f $r, ($vals -join " | ")) }
$ts = $cfg.ListObjects.Item("tblSchedule")
Write-Output "=== tblSchedule: rows=$($ts.ListRows.Count) cols=$($ts.ListColumns.Count) ==="
$depts = @{}
for ($i=1; $i -le $ts.ListRows.Count; $i++) { $d = [string]$ts.DataBodyRange.Cells.Item($i,1).Text; if ($d) { $depts[$d] = $true } }
Write-Output ("Departments: " + ($depts.Keys -join " ;; "))
Write-Output "=== tblRosterCodes ==="
$tc = $cfg.ListObjects.Item("tblRosterCodes")
for ($i=1; $i -le $tc.ListRows.Count; $i++) { Write-Output ("  code: " + [string]$tc.DataBodyRange.Cells.Item($i,1).Text + " | " + [string]$tc.DataBodyRange.Cells.Item($i,2).Text) }
$ros = $wb.Worksheets.Item("Roster")
Write-Output "=== Roster rows 1-6 colsA-E ==="
for ($r=1; $r -le 6; $r++) { $vals = @(); for ($c=1; $c -le 5; $c++) { $vals += [string]$ros.Cells.Item($r,$c).Text }; Write-Output ("R{0}: {1}" -f $r, ($vals -join " | ")) }
foreach ($lo in $ros.ListObjects) {
  Write-Output "=== $($lo.Name): rows=$($lo.ListRows.Count) cols=$($lo.ListColumns.Count) headers(first3)=$($lo.HeaderRowRange.Cells.Item(1,1).Text)|$($lo.HeaderRowRange.Cells.Item(1,2).Text)|$($lo.HeaderRowRange.Cells.Item(1,3).Text) ==="
  Write-Output ("  label row above (r$($lo.HeaderRowRange.Row - 1)): " + [string]$ros.Cells.Item($lo.HeaderRowRange.Row - 1, 1).Text + " | " + [string]$ros.Cells.Item($lo.HeaderRowRange.Row - 1, 2).Text)
  $filled = 0
  for ($i=1; $i -le $lo.ListRows.Count; $i++) { if ([string]$lo.DataBodyRange.Cells.Item($i,1).Text) { $filled++ } }
  Write-Output "  filled Attendance Name rows: $filled"
}
$wb.Close($false); $excel.Quit()
[System.Runtime.Interopservices.Marshal]::ReleaseComObject($wb) | Out-Null
[System.Runtime.Interopservices.Marshal]::ReleaseComObject($excel) | Out-Null
